import json

def render(path,result):
    payload=json.dumps(result,separators=(",",":"),allow_nan=False).replace("<","\\u003c")
    path.write_text(TEMPLATE.replace("__DATA__",payload),encoding="utf-8")

TEMPLATE=r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Danish Demand & Procurement Desk</title><style>
:root{--ink:#293b39;--muted:#62736d;--teal:#137867;--orange:#ba5c36;--line:#d5dfd8;--bg:#f3f5ef}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}.wrap{max-width:1220px;margin:auto;padding:28px 32px}header{display:flex;justify-content:space-between;gap:20px;padding-bottom:20px;border-bottom:1px solid var(--line)}.brand{font-weight:800;letter-spacing:.05em}.tag{font-size:12px;color:var(--muted)}.hero{display:grid;grid-template-columns:1.4fr 1fr;gap:50px;padding:40px 0 32px}.kicker{text-transform:uppercase;letter-spacing:.15em;font-size:11px;font-weight:800;color:var(--teal)}h1{font-size:clamp(32px,4.6vw,55px);line-height:1.07;letter-spacing:-.04em;margin:12px 0 18px}h2{font-size:23px;margin:0 0 7px;letter-spacing:-.02em}h3{font-size:15px;margin:0 0 8px}p{color:var(--muted);margin:8px 0}.small{font-size:12px;color:var(--muted)}.note{background:#e2ebe3;padding:24px;border-radius:12px;align-self:center}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin:20px 0}label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:650;color:var(--muted)}select{padding:9px 12px;border:1px solid #b9cbbf;background:white;border-radius:7px;font:inherit;color:var(--ink);min-width:115px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.card{border:1px solid var(--line);background:white;padding:18px;border-radius:12px}.value{font-size:28px;letter-spacing:-.035em;margin:5px 0}.panel{background:white;border:1px solid var(--line);padding:24px;border-radius:14px;margin-bottom:20px}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:20px}.grid>.panel{min-width:0}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin:9px 0}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}svg{width:100%;height:auto;display:block}svg text{font:11px system-ui;fill:var(--muted)}.notice{background:#fff1e3;border-left:3px solid #c98248;padding:14px 18px;color:#794c31;font-size:13px;margin:15px 0 22px}.scroll{overflow:auto;max-height:430px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;padding:10px 9px;border-bottom:1px solid #e1e9e3;font-variant-numeric:tabular-nums}th{font-weight:650;color:var(--muted);white-space:nowrap}tr:last-child td{border:0}.state{font-size:10px;padding:3px 6px;border-radius:4px;background:#e0eee4;color:#206047}.state.OPEN{background:#e4eff9;color:#315d83}.state.REJECTED,.state.REJECTED_RECONCILED{background:#f8e8df;color:#9c4b2d}details{font-size:13px}summary{cursor:pointer;font-weight:700}li{color:var(--muted);margin:9px 0}a{color:var(--teal)}footer{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin:26px 0}
@media(max-width:800px){.hero,.grid{grid-template-columns:1fr;gap:18px}.cards{grid-template-columns:repeat(2,1fr)}.wrap{padding:20px}.panel{padding:18px}.hero{padding:28px 0}header,footer{flex-wrap:wrap}}
</style></head><body><div class="wrap"><header><div class="brand">LOAD / PROCUREMENT DESK</div><span class="tag">Danish energy research · 05 · Paper only</span></header>
<section class="hero"><div><div class="kicker">Forecast the volume. Price the mismatch.</div><h1>How much electricity<br>should the desk plan?</h1><p>Compare demand forecasts, choose a service quantile, and see how volume limits change a simulated procurement plan.</p><p class="small">DK1 + DK2 · Held-out delivery: 1–29 September 2026 · UTC</p></div><div class="note"><h3>Information arrives late.</h3><p>The simulation waits 12 days before using a consumption observation. A forecast is issued at 09:00 UTC on the day before delivery.</p><p class="small">The source contains revised gross consumption, not historical publication vintages. The customer is a hypothetical 0.1% share of each zone.</p></div></section>
<div class="controls"><label for="area">Price area<select id="area"><option>DK1</option><option>DK2</option></select></label><label for="day">Delivery day<select id="day"></select></label><span id="modelLabel" class="small"></span></div><div id="forecastCards" class="cards"></div>
<div class="grid"><section class="panel"><h2>The daily demand curve</h2><p class="small">Zone gross consumption in hourly MWh. The band is a nominal 90% prediction interval, before scaling to the paper customer.</p><svg id="forecastChart" viewBox="0 0 650 280" role="img" aria-label="Actual demand, selected forecast and prediction interval"></svg><div class="legend"><span><i class="dot" style="background:#293b39"></i>Actual</span><span><i class="dot" style="background:#137867"></i>Selected forecast</span><span><i class="dot" style="background:#d9eade"></i>90% interval</span></div></section>
<section class="panel"><h2>Compare with simple forecasts</h2><p class="small">Selection uses earlier validation MAE. Lower is better. Test results are shown here.</p><div class="scroll"><table><thead><tr><th>Model</th><th>MAE, MWh</th><th>Selected</th></tr></thead><tbody id="modelRows"></tbody></table></div><p class="small">The seasonal average uses the corresponding hour 14, 21 and 28 days earlier. Ridge models also use delayed recent demand and calendar features.</p></section></div>
<div class="notice" id="coverage"></div>
<section class="panel"><div class="kicker">Procurement policy</div><h2>Balance shortage against excess volume</h2><p class="small">Assumed surcharges, not observed imbalance-market prices. Plans share the same forecast and calibration data.</p>
<div class="controls"><label for="policy">Plan quantile<select id="policy"><option value="q50">Q50 · median plan</option><option value="q80" selected>Q80 · shortage-aware</option><option value="q90">Q90 · larger buffer</option></select></label><label for="cost">Shortage / surplus charge<select id="cost"><option value="0">€50 / €50 per MWh</option><option value="1" selected>€200 / €50 per MWh</option><option value="2">€450 / €50 per MWh</option></select></label></div>
<div id="procurementCards" class="cards"></div><p class="small" id="quantileNote"></p><svg id="penaltyChart" viewBox="0 0 1100 240" role="img" aria-label="Daily mismatch charges for the three quantity policies"></svg><div class="legend"><span><i class="dot" style="background:#829992"></i>Q50</span><span><i class="dot" style="background:#137867"></i>Q80</span><span><i class="dot" style="background:#ba5c36"></i>Q90</span></div><div class="scroll"><table><thead><tr><th>Policy</th><th>Mismatch charges</th><th>Short MWh</th><th>Excess MWh</th><th>Hours covered</th><th>Capped orders</th></tr></thead><tbody id="policyRows"></tbody></table></div>
<p class="small">Planned quantity is capped at 4 MWh per zone-hour and 120 MWh per delivery day across both zones. Orders receive capacity in delivery-hour order, with DK1 first for ties.</p></section>
<section class="panel"><div class="kicker">Paper trade management</div><h2>Inspect the day's purchase plan</h2><p class="small">Uses the area, day and policy above. The later snapshot waits until all demand for the day is assumed available.</p><div class="controls"><label for="snapshot">Order snapshot<select id="snapshot"><option value="OPEN">At planning time</option><option value="SETTLED">After demand reconciliation</option></select></label><span class="small" id="snapshotTime"></span></div><div class="scroll"><table><thead><tr><th>Delivery UTC</th><th>Requested MWh</th><th>Accepted MWh</th><th>Actual MWh</th><th>Status</th><th>Risk note</th></tr></thead><tbody id="orders"></tbody></table></div><p class="small">The desk does not connect to an exchange. Price-taking purchases and later balancing are assumptions; rejected nominations still leave demand to serve.</p></section>
<details class="panel"><summary>Method, cost accounting and limitations</summary><ul>
<li>Sources: <a href="https://www.energidataservice.dk/tso-electricity/GenerationProdTypeExchange">Energinet gross consumption</a> and <a href="https://www.energidataservice.dk/tso-electricity/DayAheadPrices">day-ahead prices</a>. Gross consumption includes transmission losses. Quarter-hour prices are averaged; incomplete hours are not filled.</li>
<li>Training ends 31 May. Validation runs 15 June–14 July. Calibration runs 28 July–17 August. Testing runs 1–29 September. Gaps allow the 12-day label delay. No coefficients, model choices or residual offsets are refitted on the test period.</li>
<li>The source reports initial, preliminary and final data. Preliminary values typically have an 8–10-day delay; final revisions can occur much later. A 12-day allowance is a conservative modeling assumption, not proof that archived values were known then.</li>
<li>Point candidates are the two-week seasonal forecast, mean of corresponding hours 2–4 weeks earlier, and ridge regression with penalties 1, 10 and 100. Validation selects independently by zone. The simplest model is retained when it wins.</li>
<li>Q50/Q80/Q90 plans add the corresponding empirical quantile of signed calibration residuals to the point forecast, floored at zero. A separate absolute-residual, finite-sample split-calibration radius forms the nominal 90% interval. Time dependence and drift can invalidate its coverage assumptions.</li>
<li>For assumed shortage charge Cs and surplus charge Co, the unconstrained cost-minimizing quantile is Cs/(Cs+Co). Constant residual offsets approximate the conditional quantile; volume constraints can change the optimal joint plan.</li>
<li>Cost = actual MWh × spot price + max(actual−accepted, 0) × Cs + max(accepted−actual, 0) × Co. This assumes shortages bought at spot+Cs and excess sold at spot−Co. These are synthetic charges, not actual balancing rules or quotes.</li>
<li>All policies serve the same actual load; the spot-cost component is common. No liquidity, transaction fees, collateral, credit risk, actual customer data, weather forecasts or tariff structure are modeled.</li>
<li>Orders move PROPOSED → APPROVED → OPEN → SETTLED. A rejected order becomes REJECTED_RECONCILED after its uncovered load is accounted for. Caps, a kill switch, duplicate protection, chronological events and delayed reconciliation are implemented.</li>
<li>The saved SQLite book is Q80 at €200/€50 charges. The report also simulates Q50/Q90 and alternative charges. The 90% interval and Q90 service target are different quantities and need not have the same observed coverage.</li></ul><p class="small"><a href="metrics.json">Metrics & source records</a> · <a href="forecasts.csv">Forecasts</a> · <a href="q50_orders.csv">Q50 orders</a> · <a href="q80_orders.csv">Q80 orders</a> · <a href="q90_orders.csv">Q90 orders</a> · <a href="q80_events.csv">Q80 event history</a></p></details>
<footer><span>Danish Demand & Procurement Desk · Reproducible Python + SQLite</span><span>1,392 held-out zone-hours · 29 complete days</span></footer>
</div><script id="data" type="application/json">__DATA__</script><script>
"use strict";
const D=JSON.parse(document.getElementById("data").textContent),$=id=>document.getElementById(id),M=D.meta;
const f=(n,d=0)=>Number(n).toLocaleString("en-GB",{minimumFractionDigits:d,maximumFractionDigits:d}),e=n=>"€"+f(n),pct=n=>f(n*100,1)+"%";
const names={two_week:"Same hour, 2 weeks ago",three_week_mean:"Seasonal average, 2–4 weeks",ridge_1:"Ridge · 1",ridge_10:"Ridge · 10",ridge_100:"Ridge · 100"};
const card=(l,v,n)=>'<div class="card"><div class="small">'+l+'</div><div class="value">'+v+'</div><div class="small">'+n+'</div></div>';
const dates=[...new Set(D.forecasts.map(r=>r.delivery.slice(0,10)))];
dates.forEach(d=>{const o=document.createElement("option");o.value=d;o.textContent=d;$("day").appendChild(o)});
function path(v,w,h,lo,hi){return v.map((y,i)=>(i?"L":"M")+(55+i*(w-74)/Math.max(1,v.length-1)).toFixed(1)+","+(h-32-(h-52)*(y-lo)/(hi-lo)).toFixed(1)).join(" ")}
function axes(w,h,lo,hi){let s="";for(let i=0;i<4;i++){let y=h-32-(h-52)*i/3;s+='<line x1="55" x2="'+(w-19)+'" y1="'+y+'" y2="'+y+'" stroke="#e1e8e2"/><text x="47" y="'+(y+4)+'" text-anchor="end">'+f(lo+(hi-lo)*i/3)+'</text>'}return s}
function forecast(){
 const a=$("area").value,m=M.areas[a],s=m.test[m.selected],rows=D.forecasts.filter(r=>r.area===a&&r.delivery.startsWith($("day").value));
 $("modelLabel").textContent=names[m.selected]+" selected on validation";
 $("forecastCards").innerHTML=card("Mean absolute error",f(s.mae_mwh,1)+" MWh","Raw point forecast, full holdout")+card("Weighted absolute error",pct(s.wape),"Against total actual zone demand")+card("90% interval coverage",pct(m.interval90_coverage),"Observed on later hours")+card("Point forecast bias",f(s.bias_mwh,1)+" MWh","Negative = demand understated");
 const w=650,h=280,lo=Math.min(...rows.map(r=>r.lower90))*0.95,hi=Math.max(...rows.map(r=>Math.max(r.upper90,r.actual)))*1.04;
 let low=rows.map(r=>r.lower90),up=rows.map(r=>r.upper90),points=up.map((v,i)=>[55+i*(w-74)/23,h-32-(h-52)*(v-lo)/(hi-lo)]).concat(low.map((v,i)=>[55+i*(w-74)/23,h-32-(h-52)*(v-lo)/(hi-lo)]).reverse());
 let svg=axes(w,h,lo,hi)+'<polygon points="'+points.map(p=>p.join(",")).join(" ")+'" fill="#d9eade"/><path d="'+path(rows.map(r=>r.actual),w,h,lo,hi)+'" fill="none" stroke="#293b39" stroke-width="2.4"/><path d="'+path(rows.map(r=>r.point),w,h,lo,hi)+'" fill="none" stroke="#137867" stroke-width="2.3"/>';
 for(let i=0;i<24;i+=4)svg+='<text x="'+(55+i*(w-74)/23)+'" y="273" text-anchor="middle">'+String(i).padStart(2,"0")+":00</text>";
 $("forecastChart").innerHTML=svg;
 $("modelRows").innerHTML=Object.entries(m.test).map(([k,v])=>"<tr><td>"+names[k]+"</td><td>"+f(v.mae_mwh,1)+"</td><td>"+(k===m.selected?"Yes":"—")+"</td></tr>").join("");
 $("coverage").textContent="Coverage check: "+pct(m.interval90_coverage)+" of "+s.n+" test hours fall inside the nominal 90% interval. Its target is not a guarantee; source revisions and changing demand can affect the result.";
}
function procurement(){
 const b=D.books.find(b=>b.policy===$("policy").value),index=Number($("cost").value),s=b.scenarios[index];
 $("procurementCards").innerHTML=card("Mismatch charges",e(s.penalty_eur),"Both zones, 29 delivery days")+card("Uncovered demand",f(s.short_mwh,1)+" MWh","Actual demand above accepted quantity")+card("Excess planned volume",f(s.surplus_mwh,1)+" MWh","Accepted quantity above actual demand")+card("Hours fully covered",pct(b.service_fraction),"Empirical result after quantity limits");
 $("quantileNote").textContent="The assumed €"+s.shortage+"/€"+s.surplus+" cost ratio implies an unconstrained target of "+pct(s.critical_quantile)+". Selected plan: "+b.policy.toUpperCase()+". Quantity limits changed mismatch charges by "+e(s.cap_penalty_change_eur)+" versus the uncapped version.";
 let values=D.books.map(b=>b.scenarios[index].daily.map(d=>d.penalty)),hi=Math.max(...values.flat())*1.05+1;
 let svg=axes(1100,240,0,hi);values.forEach((v,i)=>{svg+='<path d="'+path(v,1100,240,0,hi)+'" fill="none" stroke="'+["#829992","#137867","#ba5c36"][i]+'" stroke-width="'+(D.books[i].policy===b.policy?3:1.5)+'"/>'});
 for(let i=0;i<dates.length;i+=4)svg+='<text x="'+(55+i*1026/(dates.length-1))+'" y="231">'+dates[i].slice(5)+'</text>';
 $("penaltyChart").innerHTML=svg;
 $("policyRows").innerHTML=D.books.map(b=>{const s=b.scenarios[index];return "<tr><td>"+b.policy.toUpperCase()+"</td><td>"+e(s.penalty_eur)+"</td><td>"+f(s.short_mwh,1)+"</td><td>"+f(s.surplus_mwh,1)+"</td><td>"+pct(b.service_fraction)+"</td><td>"+b.capped_orders+"</td></tr>"}).join("");
}
function orders(){
 const b=D.books.find(b=>b.policy===$("policy").value),rows=b.orders.filter(o=>o.area===$("area").value&&o.delivery.startsWith($("day").value));
 const later=$("snapshot").value==="SETTLED",cutoff=later?Date.parse($("day").value+"T00:00:00Z")+13*86400000:Date.parse(rows[0].issue),states={};
 b.events.forEach(ev=>{if(Date.parse(ev.time)<=cutoff)states[ev.id]=ev.status});
 $("snapshotTime").textContent=new Date(cutoff).toISOString().slice(0,16).replace("T"," ")+" UTC";
 $("orders").innerHTML=rows.map(o=>"<tr><td>"+o.delivery.slice(11,16)+"</td><td>"+f(o.requested,3)+"</td><td>"+f(o.accepted,3)+"</td><td>"+(later?f(o.actual,3):"Pending")+"</td><td><span class='state "+states[o.id]+"'>"+states[o.id]+"</span></td><td>"+(o.reason||"Within limits")+"</td></tr>").join("");
}
["area","day"].forEach(id=>$(id).onchange=()=>{forecast();orders()});
$("policy").onchange=()=>{procurement();orders()};$("cost").onchange=procurement;$("snapshot").onchange=orders;
forecast();procurement();orders();
</script></body></html>"""

